mapper.update:
update `user`
set invite_num = invite_num + #{num}
where address = #{address}

mapper.select:
select *
from `user`


        and `status` = #{status}


        and parent_address = #{parentAddress}


        and register_time >= #{startTime}


        and #{endTime} >= register_time


        and (
        address = #{vague}
        or parent_address = #{vague}
        or nickname like CONCAT('%', #{vague}, '%')
        )


order by uid desc
